def variants(g,bg,diag=False):
    H,W=len(g),len(g[0]); out={}
    out['adjH']=lambda i,j: j>0 and g[i][j-1]!=bg and j+1<W and g[i][j+1]!=bg
    def anyD(g,i,j):
        return any(g[i+k][j]!=bg for k in range(1,i)) and any(g[i-k][j]!=bg for k in range(1,H-i))
    out['anyV']=anyD
    def anyDrow(g,i,j):
        return any(g[i][k]!=bg for k in range(j-1,-1,-1)) and any(g[i][k]!=bg for k in range(j+1,W))
    out['anyH']=anyDrow
    def diagAdj(i,j):
        if diag and ( (j>0 and i+1<H and g[i-1][j-1]!=bg and g[i+1][j+1]!=bg) or (j+1<W and i+1<H and g[i-1][j+1]!=bg and g[i+1][j-1]!=bg)): return True
        return False
    out['diagAdj']=diagAdj
    # diagonal ANY
    def anyDiag(i,j):
        dmin=min(i,j); 
        return all(0<=i+d<H and 0<=j+d<W and g[i+d][j+d]!=bg for d in range(1,dmin+1)) and all(g[i-d][j-d]!=bg for d in range(1,dmin+1))
    out['diagAny']=anyDiag
    if not diag: del out['diagAdj']
    return out
